-- Philippines deep-dive ES/DE/FR translations (completing 334).
-- INSERT OR IGNORE throughout.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Reporte electrónico posterior a la emisión mediante el Sistema de Facturación/Recibos Electrónicos (EIS) del BIR -- Fase 1 obligatoria desde el 31 de diciembre de 2026', 'Esta página de análisis refleja la orientación pública del BIR y la información del sector disponible a principios de agosto de 2026, y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Este mandato tiene un historial documentado de cambios de fecha -- su piloto de 2022 se pausó durante aproximadamente dos años, y el plazo de la Fase 1 ya se ha desplazado una vez, de marzo de 2026 a diciembre de 2026 -- por lo que conviene confirmar la fecha y los requisitos vigentes directamente con el BIR o con un asesor fiscal filipino antes de basar en esta página sus decisiones de cumplimiento.', 'La base legal se remonta a 2018: la Ley TRAIN (RA 10963) modificó el Código Nacional de Rentas Internas para autorizar la facturación electrónica y el reporte electrónico de ventas casi en tiempo real para grandes contribuyentes y exportadores. El Reglamento de Rentas N.º 8-2022 (RR 8-2022) emitió las primeras normas de implementación y lanzó un piloto voluntario con 100 grandes contribuyentes seleccionados ("LT100") desde el 1 de julio de 2022 -- pero problemas técnicos y de capacidad obligaron al BIR a pausar el programa más adelante ese mismo año, y este permaneció detenido durante aproximadamente dos años. El RR 11-2025 retomó y amplió formalmente el mandato bajo la ley CREATE MORE en febrero de 2025, fijando un plazo del 14 de marzo de 2026 para una lista de contribuyentes más amplia -- entre ellos, grandes contribuyentes, empresas de comercio electrónico y digitales de cualquier tamaño, exportadores y usuarios de CAS/POS. Ese plazo fue a su vez sustituido antes de llegar: el RR 26-2025 (octubre de 2025) extendió la Fase 1 hasta el 31 de diciembre de 2026, descrito en otras fuentes como que la facturación electrónica se vuelve obligatoria desde el 1 de enero de 2027. Una segunda fase que extendería el mandato a las medianas y pequeñas empresas restantes aún no tiene fecha confirmada -- depende de que los propios sistemas del BIR estén listos.', 'Una factura electrónica conforme debe usar un formato de datos estructurado y legible por máquina, capaz de transmisión electrónica al BIR -- los PDF y otros formatos no estructurados ya no califican una vez que se aplica la Fase 1. El BIR no ha publicado un único esquema técnico fijo como sí lo hacen UBL o Peppol en otras partes de este seguimiento; la emisión se realiza a través de Sistemas Contables Computarizados (CAS) o sistemas de punto de venta autorizados por el BIR, o directamente mediante el portal EIS.', 'La Fase 1 abarca a los Grandes Contribuyentes, las empresas de comercio electrónico y de plataformas digitales de cualquier tamaño, los exportadores con ventas gravadas a tasa cero de IVA, los usuarios de Sistemas Contables Computarizados o sistemas POS con capacidad de facturación electrónica, y las Empresas Registradas con incentivos fiscales. Las microempresas (con ventas brutas anuales inferiores a PHP 3 millones) están exentas, pero pueden optar voluntariamente por incorporarse para acceder a incentivos de deducción de costos. Las medianas y pequeñas empresas fuera de estas categorías quedan bajo una Fase 2 sin fecha programada.', 'Prepararse implica confirmar si ya está dentro del alcance de la Fase 1 (la lista es más amplia que solo "grandes contribuyentes"), abandonar la facturación en PDF por un formato realmente estructurado, mantener vigente su permiso CAS/POS del BIR, y prever un margen de tiempo dado el historial documentado de cambios de este mandato.', 'Filipinas respalda sus normas de facturación electrónica con una estructura de cumplimiento genuinamente escalonada bajo el NIRC, modificado por la Ley TRAIN y el RR 13-2021: multas y prisión por no emitir una factura electrónica requerida, una fuerte sanción diaria o porcentual (con posible clausura permanente tras 180 días) por no transmitir datos de ventas al BIR, y sanciones aparte, más severas, por el uso deliberado de software de supresión de ventas.', 'El Buró de Rentas Internas de Filipinas opera un modelo de reporte posterior a la emisión bajo su Sistema de Facturación/Recibos Electrónicos (EIS): una factura es legalmente válida en el momento en que llega al comprador, siendo la transmisión de datos de ventas al BIR una obligación separada, no una condición previa para su validez. La base legal se remonta a la Ley TRAIN de 2018, pero el mandato operativo tiene un historial documentado de retrasos -- un piloto de 2022 se pausó durante aproximadamente dos años, y el Reglamento de Rentas N.º 26-2025 ya ha extendido el actual plazo de la Fase 1 de marzo de 2026 al 31 de diciembre de 2026 para Grandes Contribuyentes, empresas de comercio electrónico de cualquier tamaño, exportadores y usuarios de CAS/POS. El incumplimiento conlleva consecuencias reales: multas y prisión por no emitir una factura requerida (Sección 264 del NIRC), y por separado, el mayor entre el 0,1% de los ingresos netos del año anterior o PHP 10.000 por día por no transmitir datos de ventas, con posible clausura permanente del negocio tras 180 días (Sección 264-A).', '🇵🇭' FROM countries WHERE name_en = 'Philippines';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Elektronische Meldung nach Ausstellung über das Electronic Invoicing/Receipting System (EIS) des BIR -- Phase 1 verpflichtend ab dem 31. Dezember 2026', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise des BIR und Branchenberichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Dieses Mandat hat eine dokumentierte Geschichte von Terminverschiebungen -- sein Pilotprojekt von 2022 wurde für rund zwei Jahre pausiert, und die Frist für Phase 1 hat sich bereits einmal verschoben, von März 2026 auf Dezember 2026 -- bestätigen Sie daher das aktuelle Datum und die Anforderungen direkt beim BIR oder einem philippinischen Steuerberater, bevor Sie sich für Compliance-Entscheidungen auf diese Seite verlassen.', 'Die Rechtsgrundlage reicht bis 2018 zurück: Das TRAIN-Gesetz (RA 10963) änderte den National Internal Revenue Code, um elektronische Rechnungsstellung und eine nahezu in Echtzeit erfolgende elektronische Meldung von Verkaufsdaten für Großsteuerpflichtige und Exporteure zu ermöglichen. Die Revenue Regulations No. 8-2022 (RR 8-2022) erließen die ersten Durchführungsbestimmungen und starteten ab dem 1. Juli 2022 ein freiwilliges Pilotprojekt mit 100 ausgewählten Großsteuerpflichtigen ("LT100") -- technische Probleme und Kapazitätsengpässe zwangen das BIR jedoch später im selben Jahr, das Programm zu pausieren, und es blieb rund zwei Jahre lang ausgesetzt. Die RR 11-2025 nahm das Mandat im Februar 2025 im Rahmen des CREATE-MORE-Gesetzes formell wieder auf und erweiterte es, mit einer Frist zum 14. März 2026 für eine erweiterte Liste von Steuerpflichtigen -- darunter Großsteuerpflichtige, E-Commerce- und digitale Unternehmen jeder Größe, Exporteure und CAS/POS-Nutzer. Diese Frist wurde selbst noch vor ihrem Eintreten ersetzt: Die RR 26-2025 (Oktober 2025) verschob Phase 1 auf den 31. Dezember 2026, anderswo beschrieben als verpflichtende elektronische Rechnungsstellung ab dem 1. Januar 2027. Eine zweite Phase, die das Mandat auf die verbleibenden mittleren und kleinen Unternehmen ausweitet, hat noch kein bestätigtes Datum -- sie hängt davon ab, ob die eigenen Systeme des BIR bereit sind.', 'Eine konforme E-Rechnung muss ein strukturiertes, maschinenlesbares Datenformat verwenden, das zur elektronischen Übermittlung an das BIR geeignet ist -- PDFs und andere unstrukturierte Formate gelten nicht mehr, sobald Phase 1 anwendbar ist. Das BIR hat kein einziges festes technisches Schema veröffentlicht, wie es UBL oder Peppol andernorts in diesem Tracker definieren; die Ausstellung erfolgt über vom BIR zugelassene Computerized Accounting Systems (CAS) oder Kassensysteme, oder direkt über das EIS-Portal.', 'Phase 1 umfasst Großsteuerpflichtige, E-Commerce- und Digitalplattform-Unternehmen jeder Größe, Exporteure mit umsatzsteuerlich nullbesteuerten Verkäufen, Nutzer von Computerized Accounting Systems oder POS-Systemen mit E-Invoicing-Fähigkeit sowie registrierte Unternehmen (Registered Business Enterprises) mit Steueranreizen. Kleinstunternehmen (jährlicher Bruttoumsatz unter PHP 3 Millionen) sind befreit, können sich aber freiwillig anmelden, um Kostenabzugsanreize zu erhalten. Mittlere und kleine Unternehmen außerhalb dieser Kategorien fallen unter eine noch nicht terminierte Phase 2.', 'Die Vorbereitung bedeutet, zu prüfen, ob Sie bereits in den Anwendungsbereich von Phase 1 fallen (die Liste ist breiter als nur "Großsteuerpflichtige"), von PDF-Rechnungen auf ein wirklich strukturiertes Format umzusteigen, Ihre CAS/POS-BIR-Genehmigung aktuell zu halten und angesichts der dokumentierten Geschichte von Terminverschiebungen dieses Mandats einen zeitlichen Puffer einzuplanen.', 'Die Philippinen untermauern ihre E-Invoicing-Vorschriften mit einer echten, gestuften Durchsetzungsstruktur nach dem NIRC in der durch das TRAIN-Gesetz und die RR 13-2021 geänderten Fassung: Geldbußen und Freiheitsstrafen bei Nichtausstellung einer erforderlichen E-Rechnung, eine hohe tageweise oder prozentuale Strafe (mit möglicher endgültiger Schließung nach 180 Tagen) bei Nichtübermittlung von Verkaufsdaten an das BIR, und separat harte Sanktionen für die vorsätzliche Nutzung von Software zur Verkaufsunterdrückung.', 'Die philippinische Steuerbehörde Bureau of Internal Revenue betreibt unter ihrem Electronic Invoicing/Receipting System (EIS) ein Meldemodell nach Ausstellung: Eine Rechnung ist in dem Moment rechtsgültig, in dem sie den Käufer erreicht, wobei die Übermittlung der Verkaufsdaten an das BIR eine separate Pflicht ist und keine Voraussetzung für die Gültigkeit. Die Rechtsgrundlage reicht bis zum TRAIN-Gesetz von 2018 zurück, doch das operative Mandat hat eine dokumentierte Geschichte von Verzögerungen -- ein Pilotprojekt von 2022 wurde für rund zwei Jahre pausiert, und die Revenue Regulations No. 26-2025 hat die aktuelle Frist für Phase 1 bereits von März 2026 auf den 31. Dezember 2026 verschoben, für Großsteuerpflichtige, E-Commerce-Unternehmen jeder Größe, Exporteure und CAS/POS-Nutzer. Nichteinhaltung hat echte Konsequenzen: Geldbußen und Freiheitsstrafen bei Nichtausstellung einer erforderlichen Rechnung (NIRC-Abschnitt 264), und separat den höheren Betrag aus 0,1% des Nettoeinkommens des Vorjahres oder PHP 10.000 pro Tag bei Nichtübermittlung von Verkaufsdaten, mit möglicher endgültiger Geschäftsschließung nach 180 Tagen (Abschnitt 264-A).', '🇵🇭' FROM countries WHERE name_en = 'Philippines';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Déclaration électronique post-émission via le système Electronic Invoicing/Receipting System (EIS) du BIR -- Phase 1 obligatoire à partir du 31 décembre 2026', 'Cette analyse par pays reflète les orientations publiques du BIR et les informations sectorielles disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Ce mandat a un historique documenté de changements de date -- son projet pilote de 2022 a été suspendu pendant environ deux ans, et l''échéance de la Phase 1 a déjà été déplacée une fois, de mars 2026 à décembre 2026 -- confirmez donc la date et les exigences actuelles directement auprès du BIR ou d''un conseiller fiscal philippin avant de fonder toute décision de conformité sur cette page.', 'Le fondement juridique remonte à 2018 : la loi TRAIN (RA 10963) a modifié le Code national des impôts internes pour autoriser la facturation électronique et la déclaration électronique des ventes quasi en temps réel pour les grands contribuables et les exportateurs. Le règlement fiscal n° 8-2022 (RR 8-2022) a publié les premières règles de mise en œuvre et a lancé un projet pilote volontaire avec 100 grands contribuables sélectionnés ("LT100") à partir du 1er juillet 2022 -- mais des problèmes techniques et de capacité ont contraint le BIR à suspendre le programme plus tard cette année-là, et celui-ci est resté bloqué pendant environ deux ans. Le RR 11-2025 a formellement relancé et élargi le mandat en vertu de la loi CREATE MORE en février 2025, fixant une échéance au 14 mars 2026 pour une liste élargie de contribuables -- grands contribuables, entreprises de commerce électronique et numériques de toute taille, exportateurs et utilisateurs de CAS/POS notamment. Cette échéance a elle-même été remplacée avant son arrivée : le RR 26-2025 (octobre 2025) a repoussé la Phase 1 au 31 décembre 2026, décrit ailleurs comme rendant la facturation électronique obligatoire à partir du 1er janvier 2027. Une deuxième phase étendant le mandat aux moyennes et petites entreprises restantes n''a pas encore de date confirmée -- elle dépend de la disponibilité des propres systèmes du BIR.', 'Une facture électronique conforme doit utiliser un format de données structuré et lisible par machine, apte à la transmission électronique au BIR -- les PDF et autres formats non structurés ne sont plus valables une fois la Phase 1 applicable. Le BIR n''a pas publié un schéma technique fixe unique comme le font UBL ou Peppol ailleurs dans ce suivi ; l''émission passe par des systèmes comptables informatisés (CAS) ou des systèmes de point de vente autorisés par le BIR, ou directement via le portail EIS.', 'La Phase 1 couvre les grands contribuables, les entreprises de commerce électronique et de plateformes numériques de toute taille, les exportateurs avec des ventes soumises à la TVA à taux zéro, les utilisateurs de systèmes comptables informatisés ou de systèmes de point de vente disposant d''une capacité de facturation électronique, et les entreprises enregistrées (Registered Business Enterprises) bénéficiant d''incitations fiscales. Les micro-entreprises (chiffre d''affaires brut annuel inférieur à 3 millions PHP) sont exemptées mais peuvent y adhérer volontairement pour bénéficier d''incitations à la déduction des coûts. Les moyennes et petites entreprises hors de ces catégories relèvent d''une Phase 2 sans date programmée.', 'Se préparer signifie vérifier si vous relevez déjà du champ d''application de la Phase 1 (la liste est plus large que les seuls "grands contribuables"), abandonner la facturation en PDF pour un format réellement structuré, maintenir à jour votre permis CAS/POS du BIR, et prévoir une marge compte tenu de l''historique documenté de changements de ce mandat.', 'Les Philippines assortissent leurs règles de facturation électronique d''une structure d''application véritablement graduée en vertu du NIRC tel que modifié par la loi TRAIN et le RR 13-2021 : amendes et emprisonnement pour défaut d''émission d''une facture électronique requise, une lourde pénalité journalière ou proportionnelle (avec fermeture définitive possible après 180 jours) pour défaut de transmission des données de vente au BIR, et séparément des sanctions sévères pour l''utilisation délibérée de logiciels de suppression des ventes.', 'Le Bureau of Internal Revenue des Philippines exploite un modèle de déclaration post-émission dans le cadre de son système Electronic Invoicing/Receipting System (EIS) : une facture est juridiquement valide dès qu''elle atteint l''acheteur, la transmission des données de vente au BIR étant une obligation distincte plutôt qu''une condition préalable à sa validité. Le fondement juridique remonte à la loi TRAIN de 2018, mais le mandat opérationnel a un historique documenté de retards -- un projet pilote de 2022 a été suspendu pendant environ deux ans, et le règlement fiscal n° 26-2025 a déjà repoussé l''échéance actuelle de la Phase 1 de mars 2026 au 31 décembre 2026 pour les grands contribuables, les entreprises de commerce électronique de toute taille, les exportateurs et les utilisateurs de CAS/POS. Le non-respect entraîne de réelles conséquences : amendes et emprisonnement pour défaut d''émission d''une facture requise (article 264 du NIRC), et séparément, le montant le plus élevé entre 0,1 % du revenu net de l''année précédente ou 10 000 PHP par jour pour défaut de transmission des données de vente, avec fermeture définitive de l''entreprise possible après 180 jours (article 264-A).', '🇵🇭' FROM countries WHERE name_en = 'Philippines';

