INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato", "Formato de datos estructurado y legible por máquina -- los PDF y otros formatos no estructurados ya no califican una vez que se aplica la Fase 1"], ["Plataforma de reporte", "Sistema de Facturación/Recibos Electrónicos (EIS), en transición hacia el Sistema de Reporte Electrónico de Ventas (ESRS)"], ["Base legal", "Secciones 237/237-A del NIRC, modificadas por la Ley TRAIN (RA 10963), implementadas mediante RR 8-2022, RR 11-2025 y RR 26-2025"], ["Organismo regulador", "Buró de Rentas Internas (BIR)"]]', 'A diferencia de UBL o Peppol en otras partes de este seguimiento, el BIR no ha publicado un único esquema técnico fijo -- confirme la especificación vigente directamente con el BIR o con un proveedor de servicios acreditado antes de construir sobre ella.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Format", "Strukturiertes, maschinenlesbares Datenformat -- PDFs und andere unstrukturierte Formate gelten nicht mehr, sobald Phase 1 anwendbar ist"], ["Meldeplattform", "Electronic Invoicing/Receipting System (EIS), im Übergang zum Electronic Sales Reporting System (ESRS)"], ["Rechtsgrundlage", "NIRC-Abschnitte 237/237-A in der durch das TRAIN-Gesetz (RA 10963) geänderten Fassung, umgesetzt durch RR 8-2022, RR 11-2025 und RR 26-2025"], ["Aufsichtsbehörde", "Bureau of Internal Revenue (BIR)"]]', 'Anders als UBL oder Peppol andernorts in diesem Tracker hat das BIR kein einziges festes technisches Schema veröffentlicht -- bestätigen Sie die aktuelle Spezifikation direkt beim BIR oder einem akkreditierten Dienstleister, bevor Sie darauf aufbauen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format", "Format de données structuré et lisible par machine -- les PDF et autres formats non structurés ne sont plus valables une fois la Phase 1 applicable"], ["Plateforme de déclaration", "Electronic Invoicing/Receipting System (EIS), en transition vers l''Electronic Sales Reporting System (ESRS)"], ["Fondement juridique", "Articles 237/237-A du NIRC, tels que modifiés par la loi TRAIN (RA 10963), mis en œuvre via les RR 8-2022, RR 11-2025 et RR 26-2025"], ["Organisme de contrôle", "Bureau of Internal Revenue (BIR)"]]', 'Contrairement à UBL ou Peppol ailleurs dans ce suivi, le BIR n''a pas publié un schéma technique fixe unique -- confirmez la spécification actuelle directement auprès du BIR ou d''un prestataire de services accrédité avant de vous y conformer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identificador fiscal", "Número de Identificación del Contribuyente (TIN)"], ["Registro", "Inscripción mediante el portal EIS (eis.bir.gov.ph) o un proveedor CAS/POS acreditado"], ["Organismo regulador", "Buró de Rentas Internas (BIR)"], ["Certificación", "Los Sistemas Contables Computarizados (CAS) y los sistemas POS necesitan un permiso de uso vigente del BIR"]]', 'Un permiso CAS/POS vencido o inexistente constituye por sí mismo una brecha de cumplimiento, separada del formato de facturación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-ID", "Taxpayer Identification Number (TIN)"], ["Registrierung", "Anmeldung über das EIS-Portal (eis.bir.gov.ph) oder einen akkreditierten CAS/POS-Anbieter"], ["Aufsichtsbehörde", "Bureau of Internal Revenue (BIR)"], ["Zertifizierung", "Computerized Accounting Systems (CAS) und POS-Systeme benötigen eine aktuelle BIR-Nutzungsgenehmigung (Permit-to-Use)"]]', 'Eine veraltete oder fehlende CAS/POS-Genehmigung ist eine eigenständige Compliance-Lücke, unabhängig vom Rechnungsformat selbst.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identifiant fiscal", "Taxpayer Identification Number (TIN)"], ["Enregistrement", "Inscription via le portail EIS (eis.bir.gov.ph) ou un prestataire CAS/POS accrédité"], ["Organisme de contrôle", "Bureau of Internal Revenue (BIR)"], ["Certification", "Les systèmes comptables informatisés (CAS) et les systèmes de point de vente nécessitent un permis d''utilisation BIR à jour"]]', 'Un permis CAS/POS obsolète ou absent constitue en soi une lacune de conformité, distincte du format de facturation.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Campos principales", "TIN del emisor/comprador, tipo de factura, fecha, ítems detallados, desglose de IVA"], ["Formato estructurado obligatorio", "Los PDF y otros formatos no estructurados ya no califican como facturas electrónicas válidas una vez que se aplica la Fase 1"], ["Conservación", "Aplican las reglas estándar de conservación contable del BIR -- confirme el período vigente con un asesor fiscal"], ["Permiso de uso", "Los sistemas computarizados requieren un permiso previo del BIR antes de emitir electrónicamente"]]', 'Los requisitos de conservación y de permiso se suman al propio mandato de facturación -- ambos son obligaciones separadas y continuas ante el BIR, no pasos únicos de configuración.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Kernfelder", "TIN von Aussteller/Käufer, Rechnungstyp, Datum, aufgeschlüsselte Verkäufe, USt.-Aufschlüsselung"], ["Strukturiertes Format erforderlich", "PDFs und andere unstrukturierte Formate gelten nicht mehr als gültige E-Rechnungen, sobald Phase 1 anwendbar ist"], ["Aufbewahrung", "Die üblichen BIR-Buchführungs-Aufbewahrungsregeln gelten -- bestätigen Sie den aktuellen Zeitraum mit einem Steuerberater"], ["Nutzungsgenehmigung", "Computerisierte Systeme benötigen vor der elektronischen Ausstellung eine vorherige BIR-Genehmigung"]]', 'Die Aufbewahrungs- und Genehmigungspflichten kommen zum eigentlichen Rechnungsmandat hinzu -- beide sind separate, laufende BIR-Pflichten, keine einmaligen Einrichtungsschritte.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Champs principaux", "TIN de l''émetteur/de l''acheteur, type de facture, date, ventes détaillées, ventilation de la TVA"], ["Format structuré requis", "Les PDF et autres formats non structurés ne sont plus valables comme factures électroniques une fois la Phase 1 applicable"], ["Conservation", "Les règles standard de conservation comptable du BIR s''appliquent -- confirmez la durée actuelle avec un conseiller fiscal"], ["Permis d''utilisation", "Les systèmes informatisés nécessitent un permis préalable du BIR avant toute émission électronique"]]', 'Les exigences de conservation et de permis s''ajoutent au mandat de facturation lui-même -- ce sont deux obligations distinctes et continues envers le BIR, pas de simples étapes de configuration ponctuelles.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de emisión y luego reporte', 'Una factura electrónica filipina sigue esta secuencia una vez que se aplica la Fase 1 -- tenga en cuenta que esto es reporte, no clearance:', 'La factura ya está legalmente completa en cuanto llega al comprador -- no se solicita al BIR que la apruebe primero, a diferencia de los mandatos de modelo de clearance cubiertos en otras partes de este seguimiento (Colombia, Argentina, Jordania).' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Ablauf: erst ausstellen, dann melden', 'Eine philippinische E-Rechnung durchläuft diese Abfolge, sobald Phase 1 anwendbar ist -- beachten Sie, dass dies eine Meldung ist, kein Freigabemodell:', 'Die Rechnung ist bereits rechtlich vollständig, sobald sie den Käufer erreicht -- das BIR wird nicht vorab um Genehmigung gebeten, anders als bei den andernorts in diesem Tracker behandelten Freigabemodell-Mandaten (Kolumbien, Argentinien, Jordanien).' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux émission puis déclaration', 'Une facture électronique philippine suit cette séquence une fois la Phase 1 applicable -- notez qu''il s''agit d''une déclaration, pas d''une clearance :', 'La facture est déjà juridiquement complète dès qu''elle atteint l''acheteur -- il n''est pas demandé au BIR de l''approuver au préalable, contrairement aux mandats à modèle de clearance traités ailleurs dans ce suivi (Colombie, Argentine, Jordanie).' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND lc.sort_order = 0;

