INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Verkaufsdaten an das BIR übermittelt (nahezu in Echtzeit, sobald das ESRS live ist)' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Données de vente transmises au BIR (quasi en temps réel une fois l''ESRS opérationnel)' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND ls.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El BIR cruza los datos transmitidos con las declaraciones presentadas' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Das BIR gleicht die übermittelten Daten mit den eingereichten Steuererklärungen ab' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Le BIR recoupe les données transmises avec les déclarations déposées' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Philippines' AND ls.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Quién está en el alcance, y desde cuándo', '[["Grandes Contribuyentes (LTS)", "Cubiertos desde la Fase 1 (RR 11-2025 / RR 26-2025)"], ["Empresas de comercio electrónico y plataformas digitales", "Cubiertas sin importar el tamaño"], ["Exportadores (con ventas gravadas a tasa cero de IVA)", "Cubiertos"], ["Usuarios de CAS/POS con capacidad de facturación electrónica", "Cubiertos"], ["Empresas Registradas con incentivos fiscales", "Cubiertas"]]', 'La cobertura es más amplia que solo "grandes contribuyentes" -- cualquier empresa de comercio electrónico, sin importar su tamaño, ya está dentro del alcance de la Fase 1.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Wer erfasst ist, und seit wann', '[["Großsteuerpflichtige (LTS)", "Erfasst seit Phase 1 (RR 11-2025 / RR 26-2025)"], ["E-Commerce- und Digitalplattform-Unternehmen", "Erfasst unabhängig von der Größe"], ["Exporteure (umsatzsteuerlich nullbesteuert)", "Erfasst"], ["CAS/POS-Nutzer mit E-Invoicing-Fähigkeit", "Erfasst"], ["Registrierte Unternehmen mit Steueranreizen", "Erfasst"]]', 'Der Anwendungsbereich ist breiter als nur "Großsteuerpflichtige" -- jedes E-Commerce-Unternehmen, unabhängig von seiner Größe, fällt bereits unter Phase 1.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Qui est concerné, et depuis quand', '[["Grands contribuables (LTS)", "Concernés depuis la Phase 1 (RR 11-2025 / RR 26-2025)"], ["Entreprises de commerce électronique et de plateformes numériques", "Concernées quelle que soit leur taille"], ["Exportateurs (TVA à taux zéro)", "Concernés"], ["Utilisateurs de CAS/POS avec capacité de facturation électronique", "Concernés"], ["Entreprises enregistrées bénéficiant d''incitations fiscales", "Concernées"]]', 'Le champ d''application est plus large que les seuls "grands contribuables" -- toute entreprise de commerce électronique, quelle que soit sa taille, relève déjà de la Phase 1.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Exenciones y lo que aún está por llegar', '[["Microempresas", "Exentas (ventas brutas anuales inferiores a PHP 3 millones); pueden optar voluntariamente por incentivos"], ["Medianas y pequeñas empresas restantes", "Fase 2, sin fecha confirmada -- depende de que los sistemas del BIR estén listos"], ["Entidades no residentes y no registradas para IVA", "Fuera del alcance"], ["Verificación de importaciones transfronterizas", "Una iniciativa separada (Verificación Técnica Pre-Frontera / Facturación Electrónica Transfronteriza, JAO 001-2025) se dirige a las importaciones, no a la facturación de ventas nacionales"]]', 'Trate la Fase 2 como una orientación, no como una fecha -- el BIR ha indicado que la implementará una vez que sus propios sistemas estén listos, sin un cronograma confirmado todavía.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Ausnahmen und was noch kommt', '[["Kleinstunternehmen", "Befreit (jährlicher Bruttoumsatz unter PHP 3 Millionen); können sich freiwillig für Anreize anmelden"], ["Verbleibende mittlere und kleine Unternehmen", "Phase 2, kein bestätigtes Datum -- abhängig von der Bereitschaft der BIR-Systeme"], ["Gebietsfremde, nicht umsatzsteuerlich registrierte Einheiten", "Außerhalb des Anwendungsbereichs"], ["Grenzüberschreitende Einfuhrverifizierung", "Eine separate Initiative (Pre-Border Technical Verification / Cross-Border E-Invoicing, JAO 001-2025) richtet sich an Importe, nicht an die inländische Verkaufsrechnungsstellung"]]', 'Behandeln Sie Phase 2 als Richtung, nicht als Termin -- das BIR hat erklärt, sie werde folgen, sobald die eigenen Systeme bereit sind, ohne bislang bestätigten Zeitplan.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Exonérations et ce qui reste à venir', '[["Micro-entreprises", "Exonérées (chiffre d''affaires brut annuel inférieur à 3 millions PHP) ; peuvent adhérer volontairement pour bénéficier d''incitations"], ["Moyennes et petites entreprises restantes", "Phase 2, aucune date confirmée -- dépend de la disponibilité des systèmes du BIR"], ["Entités non résidentes non enregistrées à la TVA", "Hors champ"], ["Vérification transfrontalière des importations", "Une initiative distincte (Pre-Border Technical Verification / Cross-Border E-Invoicing, JAO 001-2025) vise les importations, non la facturation des ventes domestiques"]]', 'Considérez la Phase 2 comme une orientation, pas une date -- le BIR a indiqué qu''elle suivra une fois ses propres systèmes prêts, sans calendrier confirmé à ce jour.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔒 Riesgo de clausura por no transmitir, no solo una multa', NULL, NULL, 'Bajo la Sección 264-A del NIRC, no transmitir los datos de ventas al EIS conlleva el mayor entre 1/10 del 1% de los ingresos netos del año anterior o PHP 10.000 por día -- y el BIR puede ordenar la clausura permanente del negocio tras 180 días de incumplimiento continuado. Esa es una consecuencia sustancialmente más dura que una multa fija.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔒 Schließungsrisiko bei Nichtübermittlung, nicht nur eine Geldbuße', NULL, NULL, 'Nach Abschnitt 264-A des NIRC zieht die Nichtübermittlung von Verkaufsdaten an das EIS den höheren Betrag aus 1/10 von 1% des Nettoeinkommens des Vorjahres oder PHP 10.000 pro Tag nach sich -- und das BIR kann nach 180 Tagen anhaltender Nichteinhaltung die endgültige Geschäftsschließung anordnen. Das ist eine wesentlich härtere Folge als eine feste Geldbuße.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔒 Risque de fermeture en cas de défaut de transmission, pas seulement une amende', NULL, NULL, 'En vertu de l''article 264-A du NIRC, le défaut de transmission des données de vente à l''EIS entraîne le montant le plus élevé entre 1/10 de 1 % du revenu net de l''année précédente ou 10 000 PHP par jour -- et le BIR peut ordonner la fermeture définitive de l''entreprise après 180 jours de non-conformité persistante. C''est une conséquence nettement plus lourde qu''une amende forfaitaire.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Un régimen de sanciones genuinamente escalonado', NULL, NULL, 'Más allá de la sanción por no transmitir, el NIRC, modificado por la Ley TRAIN y el RR 13-2021, añade sanciones separadas: PHP 1.000-50.000 más 2-4 años de prisión por no emitir una factura electrónica requerida o falsear una transacción; PHP 25.000 (primera infracción) o PHP 50.000 (segunda) por facturas o sistemas no registrados; y PHP 500.000-10.000.000 más 2-10 años de prisión por infracciones de impresión o por el uso deliberado de software de supresión de ventas ("zapper").' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Ein wirklich gestuftes Sanktionsschema', NULL, NULL, 'Über die Übermittlungsstrafe hinaus fügt das NIRC in der durch das TRAIN-Gesetz und die RR 13-2021 geänderten Fassung weitere separate Sanktionen hinzu: PHP 1.000-50.000 plus 2-4 Jahre Freiheitsstrafe bei Nichtausstellung einer erforderlichen E-Rechnung oder Falschdarstellung einer Transaktion; PHP 25.000 (erster Verstoß) oder PHP 50.000 (zweiter) für nicht registrierte Rechnungen oder Systeme; und PHP 500.000-10.000.000 plus 2-10 Jahre Freiheitsstrafe für Druckvergehen oder die vorsätzliche Nutzung von Software zur Verkaufsunterdrückung ("Zapper").' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Un barème de sanctions véritablement gradué', NULL, NULL, 'Au-delà de la pénalité de transmission, le NIRC tel que modifié par la loi TRAIN et le RR 13-2021 ajoute des sanctions distinctes : 1 000 à 50 000 PHP plus 2 à 4 ans d''emprisonnement pour défaut d''émission d''une facture électronique requise ou fausse représentation d''une transaction ; 25 000 PHP (première infraction) ou 50 000 PHP (seconde) pour factures ou systèmes non enregistrés ; et 500 000 à 10 000 000 PHP plus 2 à 10 ans d''emprisonnement pour infractions liées à l''impression ou l''utilisation délibérée de logiciels de suppression des ventes ("zapper").' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📅 Un mandato con un historial documentado de retrasos', NULL, NULL, 'Este no es un mandato que deba tratarse como definitivo: el piloto original se pausó durante aproximadamente dos años después de 2022, y el plazo de la Fase 1 ya se ha movido una vez, de marzo de 2026 a diciembre de 2026. Prevea un margen en lugar de planificar exactamente para la fecha indicada.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📅 Ein Mandat mit dokumentierter Geschichte von Verzögerungen', NULL, NULL, 'Dies ist kein Mandat, das als endgültig feststehend behandelt werden sollte: Das ursprüngliche Pilotprojekt wurde nach 2022 für rund zwei Jahre pausiert, und die Frist für Phase 1 hat sich bereits einmal verschoben, von März 2026 auf Dezember 2026. Planen Sie einen Puffer ein, statt exakt auf das Datum hin zu planen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📅 Un mandat avec un historique documenté de retards', NULL, NULL, 'Ce n''est pas un mandat à considérer comme définitif : le projet pilote initial a été suspendu pendant environ deux ans après 2022, et l''échéance de la Phase 1 a déjà été déplacée une fois, de mars 2026 à décembre 2026. Prévoyez une marge plutôt que de planifier exactement sur la date indiquée.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Philippines' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

