INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Facture présentant une fausse représentation de la transaction', '1 000-50 000 PHP, plus 2-4 ans d''emprisonnement', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'es', 'Facturas o sistemas no registrados (1.ª / 2.ª infracción)', 'PHP 25.000 / PHP 50.000 por unidad', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'de', 'Nicht registrierte Rechnungen oder Systeme (1./2. Verstoß)', 'PHP 25.000 / PHP 50.000 pro Einheit', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Factures ou systèmes non enregistrés (1re / 2e infraction)', '25 000 PHP / 50 000 PHP par unité', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'es', 'No transmitir los datos de ventas al EIS', 'El mayor entre 0,1% de los ingresos netos del año anterior o PHP 10.000/día', 'Posible clausura permanente tras 180 días' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'de', 'Nichtübermittlung von Verkaufsdaten an das EIS', 'Höherer Betrag aus 0,1% des Nettoeinkommens des Vorjahres oder PHP 10.000/Tag', 'Endgültige Schließung nach 180 Tagen möglich' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Défaut de transmission des données de vente à l''EIS', 'Le plus élevé entre 0,1 % du revenu net de l''année précédente ou 10 000 PHP/jour', 'Fermeture définitive possible après 180 jours' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 3;

