INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Utilisation délibérée de logiciels de suppression des ventes ("zapper")', '500 000-10 000 000 PHP, plus 2-10 ans d''emprisonnement', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Philippines' AND r.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Confirme si su empresa ya está dentro del alcance de la Fase 1', 'Los Grandes Contribuyentes, las empresas de comercio electrónico/digitales de cualquier tamaño, los exportadores y los usuarios de CAS/POS ya están cubiertos -- la lista es más amplia que solo "grandes contribuyentes", así que verifique con cuidado en lugar de asumir que no le aplica.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Prüfen Sie, ob Ihr Unternehmen bereits unter Phase 1 fällt', 'Großsteuerpflichtige, E-Commerce-/Digitalunternehmen jeder Größe, Exporteure und CAS/POS-Nutzer sind bereits jetzt erfasst -- die Liste ist breiter als nur "Großsteuerpflichtige", prüfen Sie daher sorgfältig, statt anzunehmen, dass es nicht gilt.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Vérifiez si votre entreprise relève déjà du champ d''application de la Phase 1', 'Les grands contribuables, les entreprises de commerce électronique/numériques de toute taille, les exportateurs et les utilisateurs de CAS/POS sont déjà concernés -- la liste est plus large que les seuls "grands contribuables", vérifiez donc attentivement plutôt que de supposer que cela ne s''applique pas.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Abandone la facturación en PDF antes del plazo', 'El RR 26-2025 es explícito en que los PDF y otros formatos no estructurados ya no califican como facturas electrónicas válidas una vez que se aplica la Fase 1 -- confirme que su software de facturación o POS/CAS pueda producir un formato realmente estructurado y legible por máquina.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Steigen Sie vor der Frist von PDF-Rechnungen um', 'Die RR 26-2025 stellt ausdrücklich klar, dass PDFs und andere unstrukturierte Formate nicht mehr als gültige E-Rechnungen gelten, sobald Phase 1 anwendbar ist -- stellen Sie sicher, dass Ihre Rechnungs- oder POS/CAS-Software ein wirklich strukturiertes, maschinenlesbares Format erzeugen kann.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Abandonnez la facturation en PDF avant l''échéance', 'Le RR 26-2025 précise explicitement que les PDF et autres formats non structurés ne sont plus valables comme factures électroniques une fois la Phase 1 applicable -- vérifiez que votre logiciel de facturation ou POS/CAS peut produire un format réellement structuré et lisible par machine.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Registre o actualice su permiso CAS/POS ante el BIR', 'Los sistemas contables computarizados y de punto de venta usados para la facturación electrónica necesitan un permiso de uso vigente del BIR -- un permiso vencido o inexistente constituye por sí mismo una brecha de cumplimiento, separada del formato de facturación.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Registrieren oder aktualisieren Sie Ihre CAS/POS-Genehmigung beim BIR', 'Computerisierte Buchhaltungs- und Kassensysteme, die für die elektronische Rechnungsstellung verwendet werden, benötigen eine aktuelle BIR-Nutzungsgenehmigung -- eine veraltete oder fehlende Genehmigung ist eine eigenständige Compliance-Lücke, unabhängig vom Rechnungsformat selbst.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Enregistrez ou mettez à jour votre permis CAS/POS auprès du BIR', 'Les systèmes comptables informatisés et de point de vente utilisés pour la facturation électronique nécessitent un permis d''utilisation BIR à jour -- un permis obsolète ou absent constitue en soi une lacune de conformité, distincte du format de facturation.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Esté atento a las guías del BIR sobre la plataforma de transmisión ESRS', 'La transmisión de datos de ventas en tiempo real depende de que el propio Sistema de Reporte Electrónico de Ventas (ESRS) del BIR esté listo -- a mediados de 2026 aún no estaba completamente operativo, así que espere más guías técnicas antes del plazo.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Achten Sie auf BIR-Leitlinien zur ESRS-Übermittlungsplattform', 'Die Echtzeit-Übermittlung von Verkaufsdaten hängt davon ab, ob das eigene Electronic Sales Reporting System (ESRS) des BIR bereit ist -- Mitte 2026 war es noch nicht vollständig in Betrieb, rechnen Sie daher vor der Frist mit weiteren technischen Leitlinien.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Surveillez les directives du BIR sur la plateforme de transmission ESRS', 'La transmission en temps réel des données de vente dépend de la disponibilité du propre Electronic Sales Reporting System (ESRS) du BIR -- il n''était pas encore entièrement opérationnel à la mi-2026, attendez-vous donc à d''autres directives techniques avant l''échéance.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Prevea un margen -- este plazo ya se ha movido una vez', 'El mandato se pausó completamente durante unos dos años después de su piloto de 2022, y el plazo de la Fase 1 ya se desplazó de marzo de 2026 a diciembre de 2026. Planifique estar listo bien antes de la fecha, no exactamente en ella.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Planen Sie einen Puffer ein -- diese Frist hat sich bereits einmal verschoben', 'Das Mandat wurde nach seinem Pilotprojekt von 2022 für rund zwei Jahre vollständig pausiert, und die Frist für Phase 1 hat sich bereits von März 2026 auf Dezember 2026 verschoben. Planen Sie, deutlich vor dem Termin bereit zu sein, nicht genau an diesem Tag.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Prévoyez une marge -- cette échéance a déjà été déplacée une fois', 'Le mandat a été entièrement suspendu pendant environ deux ans après son projet pilote de 2022, et l''échéance de la Phase 1 a déjà été déplacée de mars 2026 à décembre 2026. Prévoyez d''être prêt bien avant la date, et non exactement à cette date.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si es una microempresa, evalúe la adhesión voluntaria frente a mantenerse exenta', 'Las microempresas (con ventas brutas anuales inferiores a PHP 3 millones) pueden acceder a incentivos de deducción de costos si se adhieren anticipadamente, aunque todavía no estén obligadas a cumplir.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie ein Kleinstunternehmen sind, wägen Sie die freiwillige Teilnahme gegen den Verbleib in der Befreiung ab', 'Kleinstunternehmen (mit einem jährlichen Bruttoumsatz unter PHP 3 Millionen) können durch eine frühzeitige freiwillige Teilnahme Kostenabzugsanreize erhalten, auch wenn sie noch nicht zur Einhaltung verpflichtet sind.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous êtes une micro-entreprise, pesez l''adhésion volontaire face au maintien de l''exonération', 'Les micro-entreprises (moins de 3 millions PHP de chiffre d''affaires brut annuel) peuvent accéder à des incitations de déduction des coûts en adhérant de manière anticipée, même si elles ne sont pas encore tenues de se conformer.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Philippines' AND s.sort_order = 5;

