INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'BIR -- Système de facturation électronique (EIS)' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Philippines' AND p.sort_order = 0;

